// ---------- Single thumbnail card ----------

const ThumbCard: React.FC<{
  thumb: Thumb;
  w: number;
  h: number;
  highlight: number; // 0..1
  drift: number;
}> = ({ thumb, w, h, highlight, drift }) => {
  const borderColor = thumb.highlighted
    ? // mix border toward orange when highlighted
      `rgba(248,102,6, ${0.25 + 0.75 * highlight})`
    : COLORS.border;

  const borderWidth = thumb.highlighted ? 1 + 1.5 * highlight : 1;
  const glow = thumb.highlighted ? highlight : 0;
  const lift = thumb.highlighted ? -10 * highlight : 0;
  const scale = thumb.highlighted ? 1 + 0.025 * highlight : 1;

  return (
    <div
      style={{
        position: "relative",
        width: w,
        height: h,
        background: COLORS.card,
        border: `${borderWidth}px solid ${borderColor}`,
        borderRadius: w * 0.04,
        overflow: "hidden",
        transform: `translateY(${drift + lift}px) scale(${scale})`,
        boxShadow: thumb.highlighted
          ? `0 ${20 * glow}px ${60 * glow}px rgba(248,102,6,${0.18 * glow}), 0 24px 64px rgba(0,0,0,0.4)`
          : "0 24px 64px rgba(0,0,0,0.4)",
        transition: "none",
      }}
    >
      {/* top-left wordmark */}
      <div
        style={{
          position: "absolute",
          top: w * 0.05,
          left: w * 0.06,
        }}
      >
        <ApifyMark size={Math.min(w, h) * 0.055} />
      </div>

      {/* content */}
      <ThumbContent variant={thumb.variant} w={w} h={h} />

      {/* orange accent corner wedge for highlighted */}
      {thumb.highlighted && (
        <div
          style={{
            position: "absolute",
            right: 0,
            bottom: 0,
            width: w * 0.22,
            height: w * 0.22,
            background: `radial-gradient(circle at bottom right, rgba(248,102,6,${0.35 * glow}), transparent 70%)`,
            pointerEvents: "none",
          }}
        />
      )}
    </div>
  );
};

