// ---------- Scene 2: 3x3 grid reveal + highlight ----------

const GridScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();

  // 3x3 grid sizing
  const gap = width * 0.022;
  const gridPaddingX = width * 0.08;
  const gridPaddingY = height * 0.09;
  const cellW = (width - gridPaddingX * 2 - gap * 2) / 3;
  const cellH = (height - gridPaddingY * 2 - gap * 2) / 3;

  // Highlight phase begins after all thumbs land (around frame 110)
  const HIGHLIGHT_START = 115;
  const highlightProgress = spring({
    frame: frame - HIGHLIGHT_START,
    fps: vfps,
    config: SPRINGS.LIQUID,
  });

  return (
    <AbsoluteFill style={sceneExit(frame, SCENE_GRID)}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          padding: `${gridPaddingY}px ${gridPaddingX}px`,
          display: "grid",
          gridTemplateColumns: `repeat(3, ${cellW}px)`,
          gridTemplateRows: `repeat(3, ${cellH}px)`,
          gap: gap,
          justifyContent: "center",
          alignContent: "center",
        }}
      >
        {THUMBS.map((thumb, i) => {
          const row = Math.floor(i / 3);
          const col = i % 3;
          // Diagonal stagger
          const diagIdx = row + col;
          const itemIn = staggeredSpring(
            frame,
            vfps,
            diagIdx,
            6,
            10,
            "LIQUID"
          );

          // Non-highlighted thumbs dim and recede a touch when highlight kicks in
          const dimmedOpacity = thumb.highlighted
            ? 1
            : interpolate(highlightProgress, [0, 1], [1, 0.42]);
          const dimmedScale = thumb.highlighted
            ? 1
            : interpolate(highlightProgress, [0, 1], [1, 0.96]);

          const baseOpacity = itemIn * dimmedOpacity;
          const baseTranslate = interpolate(itemIn, [0, 1], [40, 0]);
          const baseBlur = interpolate(itemIn, [0, 1], [10, 0]);

          // Per-thumb ambient drift (unique seed per id)
          const drift = ambientDrift(frame, 2, 80 + i * 7, `thumb-${thumb.id}`);

          return (
            <div
              key={thumb.id}
              style={{
                opacity: baseOpacity,
                transform: `translateY(${baseTranslate}px) scale(${dimmedScale})`,
                filter: `blur(${baseBlur}px)`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <ThumbCard
                thumb={thumb}
                w={cellW}
                h={cellH}
                highlight={thumb.highlighted ? highlightProgress : 0}
                drift={drift}
              />
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

// ---------- Scene 3: Outro — three highlighted cards step forward ----------

const OutroScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const highlighted = THUMBS.filter((t) => t.highlighted);

  const titleIn = springIn(frame, vfps, 4, "SNAPPY");
  const highlightIn = springIn(frame, vfps, 14, "LIQUID");

  // 3 cards side by side
  const cardW = width * 0.22;
  const cardH = cardW * 1.25;
  const gap = width * 0.025;

  return (
    <AbsoluteFill>
      {/* Title at top */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "12%",
          maxWidth: "70%",
        }}
      >
        <div
          style={{
            fontFamily: FONT_MARKETING,
            fontWeight: 600,
            fontSize: base * 0.06,
            color: COLORS.text,
            letterSpacing: "-0.025em",
            lineHeight: 1.05,
            opacity: titleIn,
            transform: `translateY(${interpolate(titleIn, [0, 1], [24, 0])}px)`,
          }}
        >
          The{" "}
          <span
            style={{
              background: COLORS.orangeTint,
              borderBottom: `${Math.max(2, base * 0.003)}px solid ${COLORS.orange}`,
              padding: `0 ${base * 0.012}px`,
              borderRadius: base * 0.008,
              clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
            }}
          >
            three to ship.
          </span>
        </div>
      </div>

      {/* 3 highlighted cards */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "55%",
          transform: "translate(-50%, -50%)",
          display: "flex",
          gap: gap,
          alignItems: "center",
        }}
      >
        {highlighted.map((thumb, i) => {
          const itemIn = staggeredSpring(
            frame,
            vfps,
            i,
            8,
            14,
            "LIQUID"
          );
          const drift = ambientDrift(frame, 3, 100 + i * 9, `outro-${thumb.id}`);
          // Subtle stagger in elevation so the middle one feels slightly forward
          const elevation = i === 1 ? -base * 0.012 : 0;

          return (
            <div
              key={thumb.id}
              style={{
                opacity: itemIn,
                transform: `translateY(${interpolate(itemIn, [0, 1], [50, elevation])}px) scale(${interpolate(itemIn, [0, 1], [0.9, 1])})`,
                filter: `blur(${interpolate(itemIn, [0, 1], [8, 0])}px)`,
              }}
            >
              <ThumbCard
                thumb={thumb}
                w={cardW}
                h={cardH}
                highlight={1}
                drift={drift}
              />
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

// ---------- Composition ----------

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={SCENE_INTRO + TRANSITION}>
        <IntroScene />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE_GRID + TRANSITION}>
        <GridScene />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE_OUTRO}>
        <OutroScene />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
